//! `keyd` client and wire shapes (issue #102): the "no verifier or key
//! material crosses the channel" contract. The stubs and the [`Client`] are
//! generated by `midlc`; the reply helpers are the daemon's (stage C4).

use alloc::vec::Vec;

use libmessenger::{Encoder, Header, Parcel, VERSION};

use super::client::Native;
use super::{errno, Error};

/// The generated `os.lazy.keyd.v1` stubs (see `idl/keyd.midl`).
pub use messenger_generated::os_lazy_keyd_v1 as wire;

/// One row of the key list: identity and counters only, never material.
pub use wire::KeyInfo;

/// Registered service name.
pub const NAME: &str = wire::SERVICE_NAME;

/// `os.lazy.keyd.appsecret.v1` (`idl/keyd_appsecret.midl`): an app's own
/// secrets, served by `keyd` on the same endpoint under a name of its own.
pub mod appsecret {
    /// The generated stubs.
    pub use messenger_generated::os_lazy_keyd_appsecret_v1 as wire;

    /// Registered service name (the interface name minus `.v1`).
    pub const NAME: &str = wire::SERVICE_NAME;
    /// The interface id every parcel of it carries (and its ACL scope).
    pub const INTERFACE: u64 = wire::INTERFACE_ID;
}

/// The interface id every `keyd` parcel carries.
pub const INTERFACE: u64 = wire::INTERFACE_ID;

/// The standard reply error field (`docs/midl.md`, "Errors"), generated by `midlc`.
use messenger_generated::errors::ERROR_FIELD;

/// Key type `Generate` accepts for HMAC keys (`Sign`).
pub const KIND_HMAC: &str = "hmac";
/// Key type `Generate` accepts for wrapping keys (`Wrap`/`Unwrap`).
pub const KIND_WRAP: &str = "wrap";

/// Largest plaintext, blob or random payload in one request or reply.
/// Sized well below the 16 KiB call buffer so a reply always fits.
pub const MAX_BYTES: usize = 8 * 1024;

/// A parcel of `method` carrying an already-encoded `body`; also the reply
/// builder for the daemon.
pub fn parcel(method: u32, body: Vec<u8>) -> Parcel {
    parcel_on(INTERFACE, method, body)
}

/// [`parcel`] of another interface the service serves
/// ([`appsecret::INTERFACE`]).
pub fn parcel_on(interface_id: u64, method: u32, body: Vec<u8>) -> Parcel {
    Parcel {
        header: Header {
            version: VERSION,
            flags: 0,
            interface_id,
            method,
            txn_id: 0,
            reply_to: 0,
            deadline_ns: 0,
        },
        body,
        objects: Vec::new(),
    }
}

/// An empty reply (Ping, or a successful void operation).
pub fn ok_reply(method: u32) -> Parcel {
    parcel(method, Vec::new())
}

/// [`ok_reply`] on `interface_id`.
pub fn ok_reply_on(interface_id: u64, method: u32) -> Parcel {
    parcel_on(interface_id, method, Vec::new())
}

/// The daemon's error answer: errno-style code plus friendly text.
pub fn error_reply(method: u32, error: Error) -> Parcel {
    error_reply_on(INTERFACE, method, error)
}

/// [`error_reply`] on `interface_id`.
pub fn error_reply_on(interface_id: u64, method: u32, error: Error) -> Parcel {
    let code = error.errno().map(|code| -code).unwrap_or(errno::EINVAL);
    let mut body = Encoder::new();
    // A structured error field cannot overflow a fresh encoder here.
    let _ = body.error(ERROR_FIELD, code as u32, error.message());
    parcel_on(interface_id, method, body.finish())
}

/// A blocking client of the `keyd` service: `Client::try_connect(Native)` for
/// an interactive command that reports "no service", `connect` for a
/// boot-time caller that waits for `keyd` to register.
pub type Client = wire::Client<Native>;

/// Why a `keyd` call failed (`keyd` declares no error codes; a refusal is its
/// errno-style code and sentence).
pub type ClientError = wire::ClientError;
